require __DIR__.'/../vendor/autoload.php';
function correctionLog(string $phase,string $requestId,array $context=[]):void{fwrite(STDOUT,json_encode(['event'=>'question_correction','phase'=>$phase,'request_id'=>$requestId,'at'=>(new DateTimeImmutable('now',new DateTimeZone('UTC')))->format(DATE_ATOM)]+$context,JSON_UNESCAPED_UNICODE)."\n");}
function correctionEvidencePages(array $sourcePages):array{$evidence=[];foreach($sourcePages as $sourcePage){$sourcePage=(int)$sourcePage;if($sourcePage<1)continue;for($page=max(1,$sourcePage-2);$page<=$sourcePage+2;$page++)$evidence[$page]=true;}$pages=array_map('intval',array_keys($evidence));sort($pages,SORT_NUMERIC);return $pages;}
function correctionFailureMessage(Throwable $error):string{$reason=mb_strtolower($error->getMessage());if(str_contains($reason,'quota exceeded'))return 'O serviço de IA está sem cota disponível. Verifique o faturamento e os limites da chave da API OpenAI.';if(str_contains($reason,'sessão do codex pro não autorizada'))return 'A sessão do Codex Pro ainda não foi autorizada no executor.';return 'Não foi possível gerar uma proposta segura para esta questão.';}
function correctionProposalShape(array $proposal):array{$options=$proposal['options']??null;return ['statement_is_string'=>is_string($proposal['statement']??null),'options_is_array'=>is_array($options),'options_count'=>is_array($options)?count($options):null,'summary_is_string'=>is_string($proposal['summary']??null)];}
function correctionCompleteOptions(array $original,array $proposal):array{if(($proposal['options']??null)===[])$proposal['options']=array_map(static fn(array $option):array=>['id'=>$option['id'],'label'=>$option['label'],'content'=>$option['content']],$original['options']??[]);return $proposal;}
function correctionNormalizeVisualAsset(array $proposal,array $evidencePages):array{$statement=$proposal["statement"]??null;if(!is_string($statement))return $proposal;if(!array_key_exists("asset_page",$proposal)&&preg_match("~!\[[^\]]*\]\(source-page-(\d+)\.png\)~",$statement,$match)===1)$proposal["asset_page"]=(int)$match[1];if(($proposal["asset_page"]??null)!==null){if(!is_int($proposal["asset_page"])||!in_array($proposal["asset_page"],$evidencePages,true))throw new RuntimeException("A proposta indicou uma página visual fora das evidências.");$proposal["statement"]=trim((string)(preg_replace("~\s*!\[[^\]]*\]\(source-page-\d+\.png\)\s*~",chr(10).chr(10),$statement)??$statement));}return $proposal;}
function correctionExtractEmbeddedImage(string $pdf,int $page,string $target):bool{$directory=dirname($target);if(!is_dir($directory)&&!mkdir($directory,0755,true)&&!is_dir($directory))return false;$prefix=$directory."/candidate-".bin2hex(random_bytes(6));exec("pdfimages -f ".$page." -l ".$page." -png ".escapeshellarg($pdf)." ".escapeshellarg($prefix),$ignored,$status);$images=glob($prefix."-*")?:[];$images=array_values(array_filter($images,static fn(string $path):bool=>is_file($path)&&@getimagesize($path)!==false));if($status!==0||$images===[])return false;usort($images,static fn(string $a,string $b):int=>(filesize($b)?:0)<=>(filesize($a)?:0));if(!rename($images[0],$target))return false;foreach(array_slice($images,1) as $image)unlink($image);return true;}
function publishCorrectionEvent(object $job,string $status):void{$url=(string)getenv("REALTIME_URL");$secret=(string)(getenv("REALTIME_INTERNAL_SECRET")?:getenv("JWT_SECRET"));if($url===""||$secret==="")return;$payload=json_encode(["userId"=>$job->requestedBy,"requestId"=>$job->id,"questionId"=>$job->questionId,"status"=>$status]);@file_get_contents($url,false,stream_context_create(["http"=>["method"=>"POST","header"=>"Content-Type: application/json\r\nX-Realtime-Secret: ".$secret."\r\n","content"=>$payload,"timeout"=>2,"ignore_errors"=>true]]));}
$em=DoctrineEntityManagerFactory::create();$requests=new DoctrineQuestionCorrectionRequestRepository($em);$job=$requests->claimNext();
if($job===null){correctionLog('idle','-');exit(0);} $started=microtime(true);$workspace='/correction-workspaces/question-correction-'.$job->id;$images=[];correctionLog('claimed',$job->id);
if(!mkdir($workspace,0700,true)&&!is_dir($workspace))throw new RuntimeException('Não foi possível preparar o ambiente isolado.');
try{
 $schema=['type'=>'object','additionalProperties'=>false,'required'=>['statement','options','summary','asset_page'],'properties'=>['statement'=>['type'=>'string'],'options'=>['type'=>'array','items'=>['type'=>'object','additionalProperties'=>false,'required'=>['id','label','content'],'properties'=>['id'=>['type'=>'string'],'label'=>['type'=>'string'],'content'=>['type'=>'string']]]],'summary'=>['type'=>'string'],'asset_page'=>['type'=>['integer','null'],'minimum'=>1]]];
 file_put_contents($workspace.'/response-schema.json',json_encode($schema,JSON_THROW_ON_ERROR));file_put_contents($workspace.'/question.json',json_encode(['question'=>$job->originalSnapshot,'instruction'=>$job->instruction],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));
 $promptPayload=json_encode(['question'=>$job->originalSnapshot,'instruction'=>$job->instruction],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);
 $sourceJobId=$job->originalSnapshot['sourcePdfJobId']??null;$pages=$job->originalSnapshot['sourcePdfPages']??[];$evidencePages=is_array($pages)?correctionEvidencePages(array_map('intval',$pages)):[];
 if(is_string($sourceJobId)&&is_array($pages)){$source=$em->find(QuestionPdfImportJobRecord::class,$sourceJobId);if($source instanceof QuestionPdfImportJobRecord&&is_file($source->documentPath))foreach($evidencePages as $page){$target=$workspace.'/source-page-'.$page;exec('pdftoppm -png -f '.$page.' -l '.$page.' -singlefile '.escapeshellarg($source->documentPath).' '.escapeshellarg($target),$ignored,$status);if($status===0&&is_file($target.'.png'))$images[]=$target.'.png';}}
 correctionLog('pdf_rendered',$job->id,['pages'=>count($images),'evidence_pages'=>$evidencePages]);
 $prompt='Use exclusivamente o snapshot abaixo e as imagens anexadas source-page-*.png (páginas de evidência, incluindo a página de origem e duas anteriores e posteriores). Não tente ler arquivos nem executar ferramentas: todos os dados autorizados estão no snapshot. Determine autonomamente, pelas páginas de evidência anexadas, se existe figura necessária à questão e qual é a sua página. Informe asset_page com essa página, ou null se não houver figura identificável com segurança; não dependa de página informada pelo usuário e não inclua Markdown ou caminho source-page no enunciado. Faça apenas correção estrutural ou de formatação. Preserve significado, gabarito, IDs, rótulos, quantidade e ordem. Não invente conteúdo. Mesmo que nenhuma alternativa mude, options deve conter todas as alternativas originais com seus IDs, rótulos e conteúdos. Devolva somente JSON conforme response-schema.json. <snapshot>' . $promptPayload . '</snapshot>';
 $command=['docker','run','--rm','--network','concursos_public','--mount','type=volume,src=concursos_correction_workspaces,dst=/correction-workspaces','--mount','type=volume,src=concursos_codex_auth,dst=/root/.codex','-w',$workspace,'concursos-codex-runner','exec','--ephemeral','--ignore-user-config','--ignore-rules','--sandbox','workspace-write','--skip-git-repo-check','--cd',$workspace];foreach($images as $image){$command[]='-i';$command[]=$image;}array_push($command,'--output-schema',$workspace.'/response-schema.json','--output-last-message',$workspace.'/proposal.json',$prompt);
 $process=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,$workspace,['PATH'=>(string)getenv('PATH')]);if(!is_resource($process))throw new RuntimeException('Não foi possível iniciar Codex.');fclose($pipes[0]);unset($pipes[0]);foreach($pipes as $pipe)stream_set_blocking($pipe,false);$timeout=max(30,(int)(getenv('CORRECTION_CODEX_TIMEOUT')?:180));$stderr='';$stdout='';correctionLog('codex_started',$job->id,['timeout_seconds'=>$timeout]);
 while(($state=proc_get_status($process))['running']){foreach([1,2] as $index){$chunk=stream_get_contents($pipes[$index]);if($index===2)$stderr.=$chunk;else $stdout.=$chunk;}if(microtime(true)-$started>$timeout){proc_terminate($process);usleep(500000);if(proc_get_status($process)['running'])proc_terminate($process,9);throw new RuntimeException('Tempo limite da análise excedido.');}usleep(200000);}foreach([1,2] as $index){$chunk=stream_get_contents($pipes[$index]);if($index===2)$stderr.=$chunk;else $stdout.=$chunk;}foreach($pipes as $pipe)fclose($pipe);$exit=proc_close($process);if($exit===-1 && isset($state['exitcode']) && $state['exitcode']>=0)$exit=$state['exitcode'];if($exit!==0)throw new RuntimeException('Codex não concluiu a proposta: '.mb_substr($stderr!==''?$stderr:$stdout,0,240));
 $proposal=json_decode((string)file_get_contents($workspace.'/proposal.json'),true,512,JSON_THROW_ON_ERROR);if(!is_array($proposal))throw new RuntimeException('Codex não retornou uma proposta válida.');$proposal=correctionNormalizeVisualAsset(correctionCompleteOptions($job->originalSnapshot,$proposal),$evidencePages);if(is_int($proposal["asset_page"]??null)&&(!isset($source)||!$source instanceof QuestionPdfImportJobRecord||!correctionExtractEmbeddedImage($source->documentPath,$proposal["asset_page"],"/app/storage/question-pdf-assets/correction-previews/".$job->id.".png")))throw new RuntimeException("Não foi possível extrair com segurança a figura da página indicada.");correctionLog('proposal_received',$job->id,correctionProposalShape($proposal));$requests->assertProposal($job->originalSnapshot,$proposal);$requests->propose($job,$proposal);publishCorrectionEvent($job,'PROPOSED');correctionLog('proposed',$job->id,['duration_ms'=>(int)((microtime(true)-$started)*1000)]);
}catch(Throwable $e){$requests->fail($job,correctionFailureMessage($e));publishCorrectionEvent($job,'FAILED');correctionLog(str_contains($e->getMessage(),'limite')?'timed_out':'failed',$job->id,['duration_ms'=>(int)((microtime(true)-$started)*1000),'reason'=>mb_substr($e->getMessage(),0,120)]);exit(1);
}finally{foreach(array_merge(['proposal.json','response-schema.json','question.json'],array_map('basename',$images)) as $file){if(is_file($workspace.'/'.$file))unlink($workspace.'/'.$file);}rmdir($workspace.'/.codex');rmdir($workspace);correctionLog('cleaned',$job->id);}
